package com.yeyamo_mobile.api.culture_service.domain;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class CultureContentTest{@Test void enforcesWorkflow(){CultureContent c=CultureContent.create(ContentType.PROVERB,"wisdom","fr-CM","CM","user-1",ContributorType.USER,SourceType.ORAL_TESTIMONY,SensitivityLevel.PUBLIC,Visibility.PUBLIC);c.submit("user-1");c.changeStatus(ContentStatus.UNDER_REVIEW);c.changeStatus(ContentStatus.APPROVED);c.changeStatus(ContentStatus.PUBLISHED);assertEquals(ContentStatus.PUBLISHED,c.getStatus());assertNotNull(c.getPublishedAt());}@Test void sensitiveContentRequiresVerification(){CultureContent c=CultureContent.create(ContentType.RITUAL,"restricted","fr-CM","CM","elder",ContributorType.USER,SourceType.COMMUNITY_ELDER,SensitivityLevel.SACRED,Visibility.PRIVATE);c.submit("elder");c.changeStatus(ContentStatus.UNDER_REVIEW);c.changeStatus(ContentStatus.APPROVED);assertThrows(IllegalStateException.class,()->c.changeStatus(ContentStatus.PUBLISHED));c.markVerified();c.changeStatus(ContentStatus.PUBLISHED);assertEquals(ContentStatus.PUBLISHED,c.getStatus());}@Test void actorMustOwnContribution(){CultureContent c=CultureContent.create(ContentType.STORY,"story","en-CM","CM","owner",ContributorType.USER,SourceType.PERSONAL_CONTRIBUTION,SensitivityLevel.PUBLIC,Visibility.PUBLIC);assertThrows(SecurityException.class,()->c.submit("other"));}}
